132→+// ParseHookInput parses Cursor hook input from stdin.
133→+func (c *CursorAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
134→+	data, err := io.ReadAll(reader)
135→+	if err != nil {
136→+		return nil, fmt.Errorf("failed to read input: %w", err)
137→+	}
138→+
139→+	if len(data) == 0 {
140→+		return nil, errors.New("empty input")
141→+	}
142→+
143→+	input := &agent.HookInput{
144→+		HookType:  hookType,
145→+		Timestamp: time.Now(),
146→+		RawData:   make(map[string]interface{}),
147→+	}
148→+
149→+	switch hookType {
150→+	case agent.HookUserPromptSubmit:
151→+		var raw userPromptSubmitRaw
152→+		if err := json.Unmarshal(data, &raw); err != nil {
153→+			return nil, fmt.Errorf("failed to parse user prompt submit: %w", err)
154→+		}
155→+		input.SessionID = raw.getSessionID()
156→+		input.SessionRef = raw.TranscriptPath
157→+		input.UserPrompt = raw.Prompt
158→+
159→+	case agent.HookSessionStart, agent.HookSessionEnd, agent.HookStop:
160→+		var raw sessionInfoRaw
161→+		if err := json.Unmarshal(data, &raw); err != nil {
162→+			return nil, fmt.Errorf("failed to parse session info: %w", err)
163→+		}
164→+		input.SessionID = raw.getSessionID()
165→+		input.SessionRef = raw.TranscriptPath
166→+
167→+	case agent.HookPreToolUse:
168→+		var raw taskHookInputRaw
169→+		if err := json.Unmarshal(data, &raw); err != nil {
170→+			return nil, fmt.Errorf("failed to parse pre-tool input: %w", err)
171→+		}
172→+		input.SessionID = raw.getSessionID()
173→+		input.SessionRef = raw.TranscriptPath
174→+		input.ToolUseID = raw.ToolUseID
175→+		input.ToolInput = raw.ToolInput
176→+
177→+	case agent.HookPostToolUse:
178→+		var raw postToolHookInputRaw
179→+		if err := json.Unmarshal(data, &raw); err != nil {
180→+			return nil, fmt.Errorf("failed to parse post-tool input: %w", err)
181→+		}
182→+		input.SessionID = raw.getSessionID()
183→+		input.SessionRef = raw.TranscriptPath
184→+		input.ToolUseID = raw.ToolUseID
185→+		input.ToolInput = raw.ToolInput
186→+		if raw.ToolResponse.AgentID != "" {
187→+			input.RawData["agent_id"] = raw.ToolResponse.AgentID
188→+		}
189→+	}
190→+
191→+	return input, nil
192→+}
