208→+// GetSessionDir returns the directory where Cursor stores session transcripts.
209→+func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
210→+	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
211→+		return override, nil
212→+	}
213→+
214→+	homeDir, err := os.UserHomeDir()
215→+	if err != nil {
216→+		return "", fmt.Errorf("failed to get home directory: %w", err)
217→+	}
218→+
219→+	projectDir := sanitizePathForCursor(repoPath)
220→+	return filepath.Join(homeDir, ".cursor", "projects", projectDir), nil
