223→+// ReadSession reads a session from Cursor's storage (JSONL transcript file).
224→+func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
225→+	if input.SessionRef == "" {
226→+		return nil, errors.New("session reference (transcript path) is required")
227→+	}
228→+
229→+	data, err := os.ReadFile(input.SessionRef)
230→+	if err != nil {
231→+		return nil, fmt.Errorf("failed to read transcript: %w", err)
232→+	}
233→+
234→+	lines, err := transcript.ParseFromBytes(data)
235→+	if err != nil {
236→+		return nil, fmt.Errorf("failed to parse transcript: %w", err)
237→+	}
238→+
239→+	return &agent.AgentSession{
240→+		SessionID:     input.SessionID,
241→+		AgentName:     c.Name(),
242→+		SessionRef:    input.SessionRef,
243→+		StartTime:     time.Now(),
244→+		NativeData:    data,
245→+		ModifiedFiles: extractModifiedFiles(lines),
246→+	}, nil
247→+}
248→+
249→+// WriteSession writes a session to Cursor's storage (JSONL transcript file).
250→+func (c *CursorAgent) WriteSession(session *agent.AgentSession) error {
251→+	if session == nil {
252→+		return errors.New("session is nil")
253→+	}
254→+
255→+	if session.AgentName != "" && session.AgentName != c.Name() {
256→+		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
257→+	}
258→+
259→+	if session.SessionRef == "" {
260→+		return errors.New("session reference (transcript path) is required")
261→+	}
262→+
263→+	if len(session.NativeData) == 0 {
264→+		return errors.New("session has no native data to write")
265→+	}
266→+
267→+	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
268→+		return fmt.Errorf("failed to write transcript: %w", err)
269→+	}
270→+
271→+	return nil
272→+}
