279→+// sanitizePathForCursor converts a path to Cursor's project directory format.
280→+var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
281→+
282→+func sanitizePathForCursor(path string) string {
283→+	return nonAlphanumericRegex.ReplaceAllString(path, "-")
284→+}
