286→+// ChunkTranscript splits a JSONL transcript at line boundaries.
287→+func (c *CursorAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
288→+	chunks, err := agent.ChunkJSONL(content, maxSize)
289→+	if err != nil {
290→+		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
291→+	}
292→+	return chunks, nil
293→+}
294→+
295→+// ReassembleTranscript concatenates JSONL chunks with newlines.
296→+func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
297→+	return agent.ReassembleJSONL(chunks), nil
298→+}
