300→+// extractModifiedFiles extracts file paths from transcript lines that contain file-modifying tools.
301→+func extractModifiedFiles(lines []transcript.Line) []string {
302→+	seen := make(map[string]bool)
303→+	var files []string
304→+
305→+	for i := range lines {
306→+		if lines[i].Role != transcript.TypeAssistant && lines[i].Type != transcript.TypeAssistant {
307→+			continue
308→+		}
309→+
310→+		var msg transcript.AssistantMessage
311→+		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
312→+			continue
313→+		}
314→+
315→+		for _, block := range msg.Content {
316→+			if block.Type != transcript.ContentTypeToolUse {
317→+				continue
318→+			}
319→+
320→+			isModifyTool := false
321→+			for _, name := range FileModificationTools {
322→+				if block.Name == name {
323→+					isModifyTool = true
324→+					break
325→+				}
326→+			}
327→+			if !isModifyTool {
328→+				continue
329→+			}
330→+
331→+			var toolInput transcript.ToolInput
332→+			if err := json.Unmarshal(block.Input, &toolInput); err != nil {
333→+				continue
334→+			}
335→+
336→+			file := toolInput.FilePath
337→+			if file == "" {
338→+				file = toolInput.NotebookPath
339→+			}
340→+			if file != "" && !seen[file] {
341→+				seen[file] = true
342→+				files = append(files, file)
343→+			}
344→+		}
345→+	}
346→+
347→+	return files
348→+}
