409→+// InstallHooks installs Cursor hooks in .cursor/hooks.json.
410→+// If force is true, removes existing Entire hooks before installing.
411→+// Returns the number of hooks installed.
412→+func (c *CursorAgent) InstallHooks(localDev bool, force bool) (int, error) {
413→+	repoRoot, err := paths.RepoRoot()
414→+	if err != nil {
415→+		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
416→+		if err != nil {
417→+			return 0, fmt.Errorf("failed to get current directory: %w", err)
418→+		}
419→+	}
420→+
421→+	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
422→+
423→+	// Read existing hooks file if it exists
424→+	var hooksFile CursorHooksFile
425→+
426→+	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
427→+	if readErr == nil {
428→+		if err := json.Unmarshal(existingData, &hooksFile); err != nil {
429→+			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
430→+		}
431→+	} else {
432→+		hooksFile.Version = 1
433→+	}
434→+
435→+	// If force is true, remove all existing Entire hooks first
436→+	if force {
437→+		hooksFile.Hooks.SessionStart = removeEntireHooks(hooksFile.Hooks.SessionStart)
438→+		hooksFile.Hooks.SessionEnd = removeEntireHooks(hooksFile.Hooks.SessionEnd)
439→+		hooksFile.Hooks.BeforeSubmitPrompt = removeEntireHooks(hooksFile.Hooks.BeforeSubmitPrompt)
440→+		hooksFile.Hooks.Stop = removeEntireHooks(hooksFile.Hooks.Stop)
441→+		hooksFile.Hooks.PreToolUse = removeEntireHooks(hooksFile.Hooks.PreToolUse)
442→+		hooksFile.Hooks.PostToolUse = removeEntireHooks(hooksFile.Hooks.PostToolUse)
443→+	}
444→+
445→+	// Define hook commands
446→+	var cmdPrefix string
447→+	if localDev {
448→+		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
449→+	} else {
450→+		cmdPrefix = "entire hooks cursor "
451→+	}
452→+
453→+	sessionStartCmd := cmdPrefix + "session-start"
454→+	sessionEndCmd := cmdPrefix + "session-end"
455→+	beforeSubmitPromptCmd := cmdPrefix + "before-submit-prompt"
456→+	stopCmd := cmdPrefix + "stop"
457→+	preTaskCmd := cmdPrefix + "pre-task"
458→+	postTaskCmd := cmdPrefix + "post-task"
459→+	postTodoCmd := cmdPrefix + "post-todo"
460→+
461→+	count := 0
462→+
463→+	// Add hooks if they don't exist
464→+	if !hookCommandExists(hooksFile.Hooks.SessionStart, sessionStartCmd) {
465→+		hooksFile.Hooks.SessionStart = append(hooksFile.Hooks.SessionStart, CursorHookEntry{Command: sessionStartCmd})
466→+		count++
467→+	}
468→+	if !hookCommandExists(hooksFile.Hooks.SessionEnd, sessionEndCmd) {
469→+		hooksFile.Hooks.SessionEnd = append(hooksFile.Hooks.SessionEnd, CursorHookEntry{Command: sessionEndCmd})
470→+		count++
471→+	}
472→+	if !hookCommandExists(hooksFile.Hooks.BeforeSubmitPrompt, beforeSubmitPromptCmd) {
473→+		hooksFile.Hooks.BeforeSubmitPrompt = append(hooksFile.Hooks.BeforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
474→+		count++
475→+	}
476→+	if !hookCommandExists(hooksFile.Hooks.Stop, stopCmd) {
477→+		hooksFile.Hooks.Stop = append(hooksFile.Hooks.Stop, CursorHookEntry{Command: stopCmd})
478→+		count++
479→+	}
480→+	if !hookCommandExistsWithMatcher(hooksFile.Hooks.PreToolUse, "Task", preTaskCmd) {
481→+		hooksFile.Hooks.PreToolUse = append(hooksFile.Hooks.PreToolUse, CursorHookEntry{Command: preTaskCmd, Matcher: "Task"})
482→+		count++
483→+	}
484→+	if !hookCommandExistsWithMatcher(hooksFile.Hooks.PostToolUse, "Task", postTaskCmd) {
485→+		hooksFile.Hooks.PostToolUse = append(hooksFile.Hooks.PostToolUse, CursorHookEntry{Command: postTaskCmd, Matcher: "Task"})
486→+		count++
487→+	}
488→+	if !hookCommandExistsWithMatcher(hooksFile.Hooks.PostToolUse, "TodoWrite", postTodoCmd) {
489→+		hooksFile.Hooks.PostToolUse = append(hooksFile.Hooks.PostToolUse, CursorHookEntry{Command: postTodoCmd, Matcher: "TodoWrite"})
490→+		count++
491→+	}
492→+
493→+	if count == 0 {
