514→+// UninstallHooks removes Entire hooks from Cursor HooksFileName.
515→+func (c *CursorAgent) UninstallHooks() error {
516→+	repoRoot, err := paths.RepoRoot()
517→+	if err != nil {
518→+		repoRoot = "."
