520→+	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
521→+	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
522→+	if err != nil {
523→+		return nil //nolint:nilerr // No hooks file means nothing to uninstall
524→+	}
525→+
526→+	var hooksFile CursorHooksFile
527→+	if err := json.Unmarshal(data, &hooksFile); err != nil {
528→+		return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
529→+	}
530→+
531→+	// Remove Entire hooks from all hook types
532→+	hooksFile.Hooks.SessionStart = removeEntireHooks(hooksFile.Hooks.SessionStart)
533→+	hooksFile.Hooks.SessionEnd = removeEntireHooks(hooksFile.Hooks.SessionEnd)
534→+	hooksFile.Hooks.BeforeSubmitPrompt = removeEntireHooks(hooksFile.Hooks.BeforeSubmitPrompt)
535→+	hooksFile.Hooks.Stop = removeEntireHooks(hooksFile.Hooks.Stop)
536→+	hooksFile.Hooks.PreToolUse = removeEntireHooks(hooksFile.Hooks.PreToolUse)
537→+	hooksFile.Hooks.PostToolUse = removeEntireHooks(hooksFile.Hooks.PostToolUse)
538→+
539→+	// Write back
540→+	output, err := jsonutil.MarshalIndentWithNewline(hooksFile, "", "  ")
541→+	if err != nil {
542→+		return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
543→+	}
544→+
545→+	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
546→+		return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
547→+	}
548→+	return nil
549→+}
