551→+// AreHooksInstalled checks if Entire hooks are installed.
552→+func (c *CursorAgent) AreHooksInstalled() bool {
553→+	repoRoot, err := paths.RepoRoot()
554→+	if err != nil {
555→+		repoRoot = "."
556→+	}
557→+	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
558→+	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
559→+	if err != nil {
560→+		return false
561→+	}
562→+
563→+	var hooksFile CursorHooksFile
564→+	if err := json.Unmarshal(data, &hooksFile); err != nil {
565→+		return false
566→+	}
567→+
568→+	return hasEntireHook(hooksFile.Hooks.Stop) ||
569→+		hasEntireHook(hooksFile.Hooks.SessionStart) ||
570→+		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt)
