957→+// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
958→+// Returns nil if the hook has no lifecycle significance.
959→+func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
960→+	switch hookName {
961→+	case HookNameSessionStart:
962→+		return c.parseSessionStart(stdin)
963→+	case HookNameBeforeSubmitPrompt:
964→+		return c.parseTurnStart(stdin)
965→+	case HookNameStop:
966→+		return c.parseTurnEnd(stdin)
967→+	case HookNameSessionEnd:
968→+		return c.parseSessionEnd(stdin)
969→+	case HookNamePreTask:
970→+		return c.parseSubagentStart(stdin)
971→+	case HookNamePostTask:
972→+		return c.parseSubagentEnd(stdin)
973→+	case HookNamePostTodo:
974→+		// PostTodo is handled outside the generic dispatcher (incremental checkpoints).
975→+		return nil, nil //nolint:nilnil // nil event = no lifecycle action
976→+	default:
977→+		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
978→+	}
979→+}
