1079→+// readAndParse reads stdin and unmarshals JSON into the given type.
1080→+func readAndParse[T any](stdin io.Reader) (*T, error) {
1081→+	data, err := io.ReadAll(stdin)
1082→+	if err != nil {
1083→+		return nil, fmt.Errorf("failed to read hook input: %w", err)
1084→+	}
1085→+	if len(data) == 0 {
1086→+		return nil, errors.New("empty hook input")
1087→+	}
1088→+	var result T
1089→+	if err := json.Unmarshal(data, &result); err != nil {
1090→+		return nil, fmt.Errorf("failed to parse hook input: %w", err)
1091→+	}
1092→+	return &result, nil
1093→+}
