 75→// ParseHookInput parses Cursor hook input from stdin.
 76→func (c *CursorAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
 77→	data, err := io.ReadAll(reader)
 78→	if err != nil {
 79→		return nil, fmt.Errorf("failed to read input: %w", err)
 80→	}
 81→
 82→	if len(data) == 0 {
 83→		return nil, errors.New("empty input")
 84→	}
 85→
 86→	input := &agent.HookInput{
 87→		HookType:  hookType,
 88→		Timestamp: time.Now(),
 89→		RawData:   make(map[string]interface{}),
 90→	}
 91→
 92→	switch hookType {
 93→	case agent.HookUserPromptSubmit:
 94→		var raw userPromptSubmitRaw
 95→		if err := json.Unmarshal(data, &raw); err != nil {
 96→			return nil, fmt.Errorf("failed to parse user prompt submit: %w", err)
 97→		}
 98→		input.SessionID = raw.getSessionID()
 99→		input.SessionRef = raw.TranscriptPath
100→		input.UserPrompt = raw.Prompt
101→
102→	case agent.HookSessionStart, agent.HookSessionEnd, agent.HookStop:
103→		var raw sessionInfoRaw
104→		if err := json.Unmarshal(data, &raw); err != nil {
105→			return nil, fmt.Errorf("failed to parse session info: %w", err)
106→		}
107→		input.SessionID = raw.getSessionID()
108→		input.SessionRef = raw.TranscriptPath
109→
110→	case agent.HookPreToolUse:
111→		var raw taskHookInputRaw
112→		if err := json.Unmarshal(data, &raw); err != nil {
113→			return nil, fmt.Errorf("failed to parse pre-tool input: %w", err)
114→		}
115→		input.SessionID = raw.getSessionID()
116→		input.SessionRef = raw.TranscriptPath
117→		input.ToolUseID = raw.ToolUseID
118→		input.ToolInput = raw.ToolInput
119→
120→	case agent.HookPostToolUse:
121→		var raw postToolHookInputRaw
122→		if err := json.Unmarshal(data, &raw); err != nil {
123→			return nil, fmt.Errorf("failed to parse post-tool input: %w", err)
124→		}
125→		input.SessionID = raw.getSessionID()
126→		input.SessionRef = raw.TranscriptPath
127→		input.ToolUseID = raw.ToolUseID
128→		input.ToolInput = raw.ToolInput
129→		if raw.ToolResponse.AgentID != "" {
130→			input.RawData["agent_id"] = raw.ToolResponse.AgentID
131→		}
132→	}
133→
134→	return input, nil
135→}
