153→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
154→		return override, nil
155→	}
156→
157→	homeDir, err := os.UserHomeDir()
158→	if err != nil {
159→		return "", fmt.Errorf("failed to get home directory: %w", err)
160→	}
161→
162→	projectDir := sanitizePathForCursor(repoPath)
163→	return filepath.Join(homeDir, ".cursor", "projects", projectDir), nil
164→}
