166→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
167→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
168→	if input.SessionRef == "" {
169→		return nil, errors.New("session reference (transcript path) is required")
170→	}
171→
172→	data, err := os.ReadFile(input.SessionRef)
173→	if err != nil {
174→		return nil, fmt.Errorf("failed to read transcript: %w", err)
175→	}
176→
177→	lines, err := transcript.ParseFromBytes(data)
178→	if err != nil {
179→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
180→	}
181→
182→	return &agent.AgentSession{
183→		SessionID:     input.SessionID,
184→		AgentName:     c.Name(),
185→		SessionRef:    input.SessionRef,
186→		StartTime:     time.Now(),
187→		NativeData:    data,
188→		ModifiedFiles: extractModifiedFiles(lines),
189→	}, nil
190→}
191→
192→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
193→func (c *CursorAgent) WriteSession(session *agent.AgentSession) error {
194→	if session == nil {
195→		return errors.New("session is nil")
196→	}
197→
198→	if session.AgentName != "" && session.AgentName != c.Name() {
199→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
200→	}
201→
202→	if session.SessionRef == "" {
203→		return errors.New("session reference (transcript path) is required")
204→	}
205→
206→	if len(session.NativeData) == 0 {
207→		return errors.New("session has no native data to write")
208→	}
209→
210→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
211→		return fmt.Errorf("failed to write transcript: %w", err)
212→	}
213→
214→	return nil
215→}
