243→// extractModifiedFiles extracts file paths from transcript lines that contain file-modifying tools.
244→func extractModifiedFiles(lines []transcript.Line) []string {
245→	seen := make(map[string]bool)
246→	var files []string
247→
248→	for i := range lines {
249→		if lines[i].Role != transcript.TypeAssistant && lines[i].Type != transcript.TypeAssistant {
250→			continue
251→		}
252→
253→		var msg transcript.AssistantMessage
254→		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
255→			continue
256→		}
257→
258→		for _, block := range msg.Content {
259→			if block.Type != transcript.ContentTypeToolUse {
260→				continue
261→			}
262→
263→			isModifyTool := false
264→			for _, name := range FileModificationTools {
265→				if block.Name == name {
266→					isModifyTool = true
267→					break
268→				}
269→			}
270→			if !isModifyTool {
271→				continue
272→			}
273→
274→			var toolInput transcript.ToolInput
275→			if err := json.Unmarshal(block.Input, &toolInput); err != nil {
276→				continue
277→			}
278→
279→			file := toolInput.FilePath
280→			if file == "" {
281→				file = toolInput.NotebookPath
282→			}
283→			if file != "" && !seen[file] {
284→				seen[file] = true
285→				files = append(files, file)
286→			}
287→		}
288→	}
289→
290→	return files
291→}
