 20→// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
 21→// Returns nil if the hook has no lifecycle significance.
 22→func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
 23→	switch hookName {
 24→	case HookNameSessionStart:
 25→		return c.parseSessionStart(stdin)
 26→	case HookNameBeforeSubmitPrompt:
 27→		return c.parseTurnStart(stdin)
 28→	case HookNameStop:
 29→		return c.parseTurnEnd(stdin)
 30→	case HookNameSessionEnd:
 31→		return c.parseSessionEnd(stdin)
 32→	case HookNamePreTask:
 33→		return c.parseSubagentStart(stdin)
 34→	case HookNamePostTask:
 35→		return c.parseSubagentEnd(stdin)
 36→	case HookNamePostTodo:
 37→		// PostTodo is handled outside the generic dispatcher (incremental checkpoints).
 38→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 39→	default:
 40→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 41→	}
 42→}
