142→// readAndParse reads stdin and unmarshals JSON into the given type.
143→func readAndParse[T any](stdin io.Reader) (*T, error) {
144→	data, err := io.ReadAll(stdin)
145→	if err != nil {
146→		return nil, fmt.Errorf("failed to read hook input: %w", err)
147→	}
148→	if len(data) == 0 {
149→		return nil, errors.New("empty hook input")
150→	}
151→	var result T
152→	if err := json.Unmarshal(data, &result); err != nil {
153→		return nil, fmt.Errorf("failed to parse hook input: %w", err)
154→	}
155→	return &result, nil
156→}
