234→// Helper functions for hook management
235→
236→func hookCommandExists(entries []CursorHookEntry, command string) bool {
237→	for _, entry := range entries {
238→		if entry.Command == command {
239→			return true
240→		}
241→	}
242→	return false
243→}
244→
245→func hookCommandExistsWithMatcher(entries []CursorHookEntry, matcher, command string) bool {
246→	for _, entry := range entries {
247→		if entry.Matcher == matcher && entry.Command == command {
248→			return true
249→		}
250→	}
251→	return false
252→}
253→
254→func isEntireHook(command string) bool {
255→	for _, prefix := range entireHookPrefixes {
256→		if strings.HasPrefix(command, prefix) {
257→			return true
258→		}
259→	}
260→	return false
261→}
262→
263→func hasEntireHook(entries []CursorHookEntry) bool {
264→	for _, entry := range entries {
265→		if isEntireHook(entry.Command) {
266→			return true
267→		}
268→	}
269→	return false
270→}
271→
272→func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
273→	result := make([]CursorHookEntry, 0, len(entries))
274→	for _, entry := range entries {
275→		if !isEntireHook(entry.Command) {
276→			result = append(result, entry)
277→		}
278→	}
279→	return result
280→}
